/* 状态模拟 / 静态快照：门户卡片在真实产品里是 HoverCard.module.css 的 .card
   （position: fixed，left/top 由 JS 写入）；这里拉回文档流，同时保留它作为卡片内容的
   包含块。 */
.card.snapshotStatic { position: relative; inset: auto; }

/* 状态模拟 / 静态快照：门户卡片在真实产品里是 HoverCard.module.css 的 .card
   （position: fixed，left/top 由 JS 写入）；这里拉回文档流，同时保留它作为卡片内容的
   包含块。 */
.card.snapshotStatic { position: relative; inset: auto; }

/* 状态模拟：.ruleIntervalArrows 平时 opacity:0，只在步进器 :hover / :focus-within
   时显现；静态快照把那条规则原样搬到 .forceArrows 上。 */
.ruleIntervalStepper.forceArrows .ruleIntervalArrows { opacity: 1; }

/* 静态快照：Modal 的 .root 是 body 上的 fixed 全屏遮罩层，这里改成文档流内的
   相对定位，同时保留它作为 .mask 绝对定位的父级。 */
.root.snapshotStatic { position: relative; inset: auto; }
